function hitCurrentHero() {
    if(!hitHeroArt||hitHeroArt.id!==gameData.character)
        hitTrackHero({id:gameData.character,row:0,column:0,flip:false},0,0,{x:0,y:0});
    return hitHeroArt;
}
// Exact continuous rectangle vs rectangle intersection over one simulation tick.
